∃ (a_range : Set ℝ), 
    a_range = {a : ℝ | a > 0 ∧ 
      let f := fun x => (Real.cot x + x) / (1 - x * Real.cot x)
      let A := {x : ℝ | (deriv f) x > 0}
      let B := {x : ℝ | x^2 - 2*a*x + 3 ≤ 0}
      ∃ (s : Finset ℤ), s.card = 2 ∧ ∀ n : ℤ, (n : ℝ) ∈ A ∩ B ↔ n ∈ s}

(∀ a b : ℝ, a > 0 → b > 0 → 
    let f := fun x => Real.log (b * x + Real.sqrt (a^2 + b^2 * x^2))
    deriv f = fun x => (b * Real.sqrt (a^2 + b^2 * x^2) + b * x) / (b * x + Real.sqrt (a^2 + b^2 * x^2))^2)

∃ (θ : ℝ) (simplified_expr : ℚ → ℚ),

    (∑ k in Finset.range 44, 
      if k = 0 then Real.cos (2 * Real.pi / 180)
      else if k = 1 then -Real.sin (4 * Real.pi / 180)
      else if k = 2 then -Real.cos (6 * Real.pi / 180)
      else Real.sin ((2 * k + 2) * Real.pi / 180)) = 
    (1 / Real.cos θ) - Real.tan θ ∧

    (∀ x : ℚ, 6 * x^2 - x - 2 ≠ 0 → 
      (4 * x^2 - 4 * x - 3) / (6 * x^2 - x - 2) = simplified_expr x) ∧

    (θ > 0 ∧ θ < 180)

∃ n : ℕ, n > 0 ∧ 
  (∀ m : ℕ, m > 0 → 
    let t := fun k => if k = 1 then 5 else 5 + ∑ i in Finset.range (k - 1), (2 * (i + 2) + 3)
    let a := fun k => ((t k)^2 + 1000) / (t k) * Real.log (((t k)^2 + (t k) + 1000) / ((t k)^2 + 1000))
    a n ≤ a m)
